CREATE TYPE "WebhookDeliveryStatus" AS ENUM ('PENDING', 'PROCESSING', 'DELIVERED', 'DEAD');
CREATE TABLE "ApiToken" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"createdById" TEXT NOT NULL,"name" TEXT NOT NULL,"prefix" TEXT NOT NULL,"secretHash" TEXT NOT NULL,"scopes" TEXT[],"expiresAt" TIMESTAMP(3),"lastUsedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ApiToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ApiIdempotency" ("tokenId" TEXT NOT NULL,"key" TEXT NOT NULL,"route" TEXT NOT NULL,"statusCode" INTEGER NOT NULL,"response" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ApiIdempotency_pkey" PRIMARY KEY ("tokenId","key","route"));
CREATE TABLE "WebhookSubscription" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"projectId" TEXT,"name" TEXT NOT NULL,"url" TEXT NOT NULL,"events" TEXT[],"secretHash" TEXT NOT NULL,"encryptedSecret" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WebhookSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebhookDelivery" ("id" TEXT NOT NULL,"subscriptionId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"event" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" "WebhookDeliveryStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"responseStatus" INTEGER,"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WebhookDelivery_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ApiToken_prefix_key" ON "ApiToken"("prefix"); CREATE UNIQUE INDEX "ApiToken_secretHash_key" ON "ApiToken"("secretHash"); CREATE INDEX "ApiToken_workspaceId_revokedAt_createdAt_idx" ON "ApiToken"("workspaceId","revokedAt","createdAt");
CREATE INDEX "ApiIdempotency_createdAt_idx" ON "ApiIdempotency"("createdAt");
CREATE INDEX "WebhookSubscription_workspaceId_enabled_idx" ON "WebhookSubscription"("workspaceId","enabled"); CREATE INDEX "WebhookSubscription_projectId_idx" ON "WebhookSubscription"("projectId");
CREATE UNIQUE INDEX "WebhookDelivery_subscriptionId_eventId_key" ON "WebhookDelivery"("subscriptionId","eventId"); CREATE INDEX "WebhookDelivery_status_availableAt_idx" ON "WebhookDelivery"("status","availableAt"); CREATE INDEX "WebhookDelivery_subscriptionId_createdAt_idx" ON "WebhookDelivery"("subscriptionId","createdAt");
ALTER TABLE "ApiToken" ADD CONSTRAINT "ApiToken_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ApiToken" ADD CONSTRAINT "ApiToken_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ApiIdempotency" ADD CONSTRAINT "ApiIdempotency_tokenId_fkey" FOREIGN KEY ("tokenId") REFERENCES "ApiToken"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WebhookSubscription" ADD CONSTRAINT "WebhookSubscription_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "WebhookSubscription" ADD CONSTRAINT "WebhookSubscription_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WebhookDelivery" ADD CONSTRAINT "WebhookDelivery_subscriptionId_fkey" FOREIGN KEY ("subscriptionId") REFERENCES "WebhookSubscription"("id") ON DELETE CASCADE ON UPDATE CASCADE;
